import{_ as e,o as t,c as s,a2 as n}from"./chunks/framework.D3fmyz3M.js";const u=JSON.parse('{"title":"微前端是什么","description":"从拆分、集成、隔离三个关键词理解微前端的本质。","frontmatter":{"title":"微前端是什么","description":"从拆分、集成、隔离三个关键词理解微前端的本质。"},"headers":[],"relativePath":"guide/what-is.md","filePath":"guide/what-is.md","lastUpdated":1792674288000}'),r={name:"guide/what-is.md"};function o(i,a,d,l,p,h){return t(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="微前端是什么" tabindex="-1">微前端是什么 <a class="header-anchor" href="#微前端是什么" aria-label="Permalink to &quot;微前端是什么&quot;">​</a></h1><p>一句话定义：</p><blockquote><p>微前端是一种把<strong>多个可独立开发、独立部署的前端应用</strong>，在运行时或构建时组合成一个用户可见产品的架构方式。</p></blockquote><p>关键词有三个：<strong>独立</strong>、<strong>组合</strong>、<strong>隔离</strong>。</p><h2 id="它不是-多个-vue-项目放一起" tabindex="-1">它不是“多个 Vue 项目放一起” <a class="header-anchor" href="#它不是-多个-vue-项目放一起" aria-label="Permalink to &quot;它不是“多个 Vue 项目放一起”&quot;">​</a></h2><p>很多团队第一次做微前端，会把几个子项目用路由懒加载拼起来。这只是代码分割，不是微前端。真正的微前端要满足：</p><table tabindex="0"><thead><tr><th>能力</th><th>说明</th></tr></thead><tbody><tr><td>独立开发</td><td>子应用有自己的仓库、依赖、构建与发布节奏</td></tr><tr><td>独立部署</td><td>子应用上线不需要主应用重新构建</td></tr><tr><td>运行时组合</td><td>主应用在浏览器里按需加载子应用，而非打包时写死</td></tr><tr><td>故障隔离</td><td>一个子应用报错，不应拖垮整个页面</td></tr></tbody></table><p>最后一条最容易被忽略。没有隔离的“微前端”，只是“微服务化的前端代码”。</p><h2 id="三个核心问题" tabindex="-1">三个核心问题 <a class="header-anchor" href="#三个核心问题" aria-label="Permalink to &quot;三个核心问题&quot;">​</a></h2><p>任何微前端方案，本质上都在回答三个问题。</p><h3 id="_1-怎么拆分" tabindex="-1">1. 怎么拆分？ <a class="header-anchor" href="#_1-怎么拆分" aria-label="Permalink to &quot;1. 怎么拆分？&quot;">​</a></h3><p>按业务域拆，而不是按技术层拆。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>✅ 订单域 / 商品域 / 客户域 / 数据看板</span></span>
<span class="line"><span>❌ 页面层 / 组件层 / 工具层</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>按业务域拆，团队边界清晰，发布节奏独立；按技术层拆，会制造大量跨团队联调。</p><h3 id="_2-怎么集成" tabindex="-1">2. 怎么集成？ <a class="header-anchor" href="#_2-怎么集成" aria-label="Permalink to &quot;2. 怎么集成？&quot;">​</a></h3><table tabindex="0"><thead><tr><th>集成方式</th><th>代表方案</th><th>特点</th></tr></thead><tbody><tr><td>页面级嵌入</td><td>iframe</td><td>隔离最强，体验与通信最弱</td></tr><tr><td>运行时加载</td><td>single-spa、qiankun、micro-app、wujie</td><td>主应用控制挂载与卸载</td></tr><tr><td>构建时共享</td><td>Module Federation</td><td>以模块为单位共享，构建期确定依赖</td></tr><tr><td>标准组件</td><td>Web Components</td><td>浏览器原生组件模型，跨框架</td></tr></tbody></table><h3 id="_3-怎么隔离" tabindex="-1">3. 怎么隔离？ <a class="header-anchor" href="#_3-怎么隔离" aria-label="Permalink to &quot;3. 怎么隔离？&quot;">​</a></h3><p>需要隔离的资源包括：</p><ul><li><strong>JS</strong>：全局变量、原型链、定时器、事件监听。</li><li><strong>CSS</strong>：全局选择器、<code>@keyframes</code>、字体、<code>!important</code>。</li><li><strong>DOM</strong>：根节点、弹窗挂载点、<code>document</code> 查询。</li><li><strong>存储与网络</strong>：<code>localStorage</code>、Cookie、请求拦截器。</li></ul><p>没有一种方案能零成本全隔离。选型的本质，是在<strong>隔离强度</strong>、<strong>接入成本</strong>、<strong>用户体验</strong>之间取平衡。</p><h2 id="一个直观对比" tabindex="-1">一个直观对比 <a class="header-anchor" href="#一个直观对比" aria-label="Permalink to &quot;一个直观对比&quot;">​</a></h2><p>以“订单子应用”为例，不同方案下的运行形态：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>iframe           独立的浏览上下文，DOM 树完全分离</span></span>
<span class="line"><span>Web Components   主文档内的 Shadow DOM，样式隔离、JS 共享</span></span>
<span class="line"><span>single-spa       主文档内的普通 DOM，无隔离</span></span>
<span class="line"><span>qiankun          主文档内的普通 DOM + Proxy 沙箱 + 样式前缀</span></span>
<span class="line"><span>micro-app        主文档内的 Shadow DOM + 类 Web Component 标签</span></span>
<span class="line"><span>wujie            iframe 执行 JS + Shadow DOM 承载视图</span></span>
<span class="line"><span>Module Federation 不是页面，而是被 import 的远程模块</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><h2 id="与相近概念的区别" tabindex="-1">与相近概念的区别 <a class="header-anchor" href="#与相近概念的区别" aria-label="Permalink to &quot;与相近概念的区别&quot;">​</a></h2><h3 id="微前端-vs-组件库" tabindex="-1">微前端 vs 组件库 <a class="header-anchor" href="#微前端-vs-组件库" aria-label="Permalink to &quot;微前端 vs 组件库&quot;">​</a></h3><p>组件库解决“复用 UI 与逻辑”，微前端解决“独立应用的组合与治理”。组件库不涉及独立部署与运行时隔离。</p><h3 id="微前端-vs-monorepo" tabindex="-1">微前端 vs Monorepo <a class="header-anchor" href="#微前端-vs-monorepo" aria-label="Permalink to &quot;微前端 vs Monorepo&quot;">​</a></h3><p>Monorepo 解决“多包同仓管理”，仍然是一个构建、一个发布单元。微前端强调独立发布。两者可以同时使用。</p><h3 id="微前端-vs-iframe-嵌套" tabindex="-1">微前端 vs iframe 嵌套 <a class="header-anchor" href="#微前端-vs-iframe-嵌套" aria-label="Permalink to &quot;微前端 vs iframe 嵌套&quot;">​</a></h3><p>iframe 是微前端的一种实现，但微前端还包括路由、通信、治理等一整套工程能力。</p><h2 id="什么时候它才成立" tabindex="-1">什么时候它才成立 <a class="header-anchor" href="#什么时候它才成立" aria-label="Permalink to &quot;什么时候它才成立&quot;">​</a></h2><p>微前端成立的前提通常包括：</p><ul><li>有多个团队，且团队希望独立发布。</li><li>系统足够大，单仓构建与回归成本已经明显。</li><li>存在技术栈差异，或存在短期内无法重写的老系统。</li><li>组织愿意为基建、规范、监控投入人力。</li></ul><p>如果只有一个小团队、一个技术栈、一个发布节奏，微前端大概率是负收益。下一篇会展开讲判断标准。</p><p>继续阅读：<a href="/micro-frontend-docs/guide/when-to-use">何时用，何时不用</a>。</p>`,35)])])}const b=e(r,[["render",o]]);export{u as __pageData,b as default};
